<script setup lang="ts">
/**
 * Several independent choices, all visible (`design/components/checkbox-group.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/checkbox-group.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef } from 'vue'

import { Icon, agentMember } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/checkbox-group.module.css'

export type CheckboxGroupOrientation = NonNullable<CheckboxGroupProps['orientation']>

export interface CheckboxGroupOption {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export interface CheckboxGroupProps {
  ariaDescribedby?: string
  /**
   * Set by FormField, because the group's question is the field's label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  defaultValue?: string[]
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * Set on every box, with each option's `value`, which is the native multi-value form data.
   */
  name?: string
  /**
   * Items render from data, because free-form children invite custom layouts (Radio's law).
   */
  options: CheckboxGroupOption[]
  /**
   * Horizontal only for ≤3 short labels without descriptions (Radio's guidance, not enforced).
   */
  orientation?: 'horizontal' | 'vertical'
  value?: string[]
}

defineOptions({ name: 'CheckboxGroup', inheritAttrs: false, controlKind: 'group' })

const props = withDefaults(defineProps<CheckboxGroupProps>(), {
  ariaRequired: undefined,
  disabled: false,
  invalid: false,
  orientation: 'vertical',
})
const emit = defineEmits<{ change: [values: string[]] }>()
const uid = useId()
const mirror = ref(props.defaultValue ?? [])
const group = useTemplateRef<HTMLElement>('group')
const current = computed(() => props.value ?? mirror.value)
const toggle = computed(
  () => (optionValue: string, checked: boolean) =>
    ((next: string[]) => ((mirror.value = next), emit('change', next)))(
      props.options
        .filter((option) =>
          option.value === optionValue ? checked : current.value.includes(option.value),
        )
        .map((option) => option.value),
    ),
)
const choose = computed(
  () => (chosen: readonly string[]) =>
    ((next: string[]) =>
      next.length === current.value.length && next.every((each) => current.value.includes(each))
        ? undefined
        : ((mirror.value = next), emit('change', next)))(
      props.options
        .filter((option) =>
          props.disabled || option.disabled === true
            ? current.value.includes(option.value)
            : chosen.includes(option.value),
        )
        .map((option) => option.value),
    ),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'CheckboxGroup',
    element: () => group.value,
    state: () => ({
      value: current.value,
      options: props.options.map((option) => ({
        id: option.value,
        label: option.label,
        ...(option.disabled === true ? { disabled: true } : {}),
      })),
      disabled: props.disabled,
      invalid: props.invalid,
    }),
    actions: { choose: { argument: 'ids', run: (value) => choose.value(value) } },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <div
    ref="group"
    :class="styles.group"
    :id="id"
    role="group"
    :data-orientation="orientation"
    :data-invalid="invalid ? '' : undefined"
    :data-disabled="disabled ? '' : undefined"
    :data-required="ariaRequired ? '' : undefined"
    :aria-label="ariaLabel"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-invalid="invalid ? true : undefined"
    data-member="checkbox-group"
  >
    <template v-for="(option, index) in options" :key="option.value">
      <div
        :class="styles.item"
        :data-disabled="disabled || option.disabled === true ? '' : undefined"
      >
        <!-- row -->
        <label
          :class="styles.row"
          :data-state="current.includes(option.value) ? 'checked' : 'unchecked'"
          :data-disabled="disabled || option.disabled === true ? '' : undefined"
        >
          <!-- box -->
          <button
            :class="styles.box"
            type="button"
            role="checkbox"
            :value="option.value"
            :aria-checked="current.includes(option.value)"
            :disabled="disabled || option.disabled === true"
            :aria-describedby="
              option.description !== undefined
                ? `${id ?? uid}-option-${index}-description`
                : undefined
            "
            :data-state="current.includes(option.value) ? 'checked' : 'unchecked'"
            :data-disabled="disabled || option.disabled === true ? '' : undefined"
            @click="toggle(option.value, !current.includes(option.value))"
            @keydown="$event.key === 'Enter' && $event.preventDefault()"
          >
            <span
              v-if="current.includes(option.value)"
              :class="styles.indicator"
              data-state="checked"
            >
              <Icon name="confirm" size="sm" />
            </span>
          </button>
          <span :class="styles.label">
            {{ option.label }}
          </span>
        </label>
        <span
          v-if="option.description !== undefined"
          :class="styles.description"
          :id="`${id ?? uid}-option-${index}-description`"
        >
          {{ option.description }}
        </span>
        <input
          v-if="name !== undefined && current.includes(option.value)"
          type="hidden"
          :name="name"
          :value="option.value"
        />
      </div>
    </template>
  </div>
</template>
